mapper.sql:
select 
  from srm_claim k join mst_cust c on c.cust_id = k.cust_id
 where k.created_at >= (#{c.from}::date)::timestamp at time zone #{c.zone}
   and k.created_at < (#{c.to}::date + 1)::timestamp at time zone #{c.zone}
and k.status = #{c.status}

   and (k.claim_no ilike #{c.keywordLike} escape '\' or k.title ilike #{c.keywordLike} escape '\'
        or c.cust_cd ilike #{c.keywordLike} escape '\' or c.cust_nm ilike #{c.keywordLike} escape '\'
        or exists (select 1 from srm_claim_ncr n where n.claim_id = k.claim_id and n.ncr_no ilike #{c.keywordLike} escape '\'))

mapper.update:
update srm_claim
   set action_cd = #{v.actionCd}, title = #{v.title}, request_text = #{v.requestText}, reply_due = #{v.replyDue},
       charge_amt = #{v.chargeAmt}, currency_cd = #{v.currencyCd}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where claim_id = #{claimId} and status = 'DRAFT' and row_ver = #{rowVer}

update srm_claim
   set status = 'SENT', sent_at = now(), sent_by = #{by}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where claim_id = #{claimId} and status = 'DRAFT' and row_ver = #{rowVer}

update srm_claim
   set status = 'ANSWERED', answer_cause = #{cause}, answer_action = #{action}, answered_on = #{on},
       answer_source = 'MANUAL', answered_by = #{by},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where claim_id = #{claimId} and status in ('SENT', 'ANSWERED') and row_ver = #{rowVer}

update srm_claim
   set status = 'ANSWERED', answer_cause = #{cause}, answer_action = #{action}, answered_on = #{on},
       answer_source = 'PORTAL', answered_by = #{by},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where claim_id = #{claimId} and status = 'SENT' and row_ver = #{rowVer}

update srm_claim
   set status = 'SENT', row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where claim_id = #{claimId} and status = 'ANSWERED' and row_ver = #{rowVer}

update srm_claim
   set status = 'CLOSED', closed_at = now(), closed_by = #{by}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where claim_id = #{claimId} and status = 'ANSWERED' and row_ver = #{rowVer}

update srm_claim
   set status = 'CANCELLED', cancel_reason = #{reason}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where claim_id = #{claimId} and status in ('DRAFT', 'SENT') and row_ver = #{rowVer}
